using UnityEngine;\nusing UnityEngine.UI;\nusing TMPro;\n\n/// <summary>\nMain HUD manager displaying all combat information.\n/// </summary>\npublic class HUDManager : MonoBehaviour\n{\n    [SerializeField] private Character playerCharacter;\n    [SerializeField] private Character opponentCharacter;\n    [SerializeField] private TextMeshProUGUI roundTimerText;\n    [SerializeField] private TextMeshProUGUI roundText;\n    [SerializeField] private Image playerHealthBar;\n    [SerializeField] private Image opponentHealthBar;\n    [SerializeField] private ComboCounterUI playerComboUI;\n    [SerializeField] private ComboCounterUI opponentComboUI;\n    \n    private float timeElapsed = 0f;\n    private float totalRoundTime = 180f;\n    \n    private void Start()\n    {\n        if (roundText != null)\n        {\n            int currentRound = GameManager.Instance?.GetCurrentRound() ?? 1;\n            int maxRounds = GameManager.Instance?.GetMaxRounds() ?? 3;\n            roundText.text = $\"Round {currentRound}/{maxRounds}\";\n        }\n    }\n    \n    private void Update()\n    {\n        UpdateRoundTimer();\n    }\n    \n    private void UpdateRoundTimer()\n    {\n        if (roundTimerText == null)\n            return;\n        \n        float timeRemaining = GameManager.Instance?.GetRoundTimeRemaining() ?? 180f;\n        int minutes = (int)(timeRemaining / 60f);\n        int seconds = (int)(timeRemaining % 60f);\n        \n        roundTimerText.text = $\"{minutes:00}:{seconds:00}\";\n        \n        // Change color if time running out\n        if (timeRemaining < 30f)\n        {\n            roundTimerText.color = Color.red;\n        }\n        else if (timeRemaining < 60f)\n        {\n            roundTimerText.color = Color.yellow;\n        }\n    }\n}\n"